package com.healthwise.analysis.service;import com.healthwise.analysis.dto.AnalysisDtos.*;import com.healthwise.analysis.entity.AnalysisHistory;import com.healthwise.analysis.repository.AnalysisHistoryRepository;import com.healthwise.exception.ResourceNotFoundException;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;
@Service public class AnalysisService{private final AnalysisHistoryRepository r;public AnalysisService(AnalysisHistoryRepository x){r=x;}private Response dto(AnalysisHistory e){return new Response(e.getId(),e.getReportId(),e.getAnalyzedAt(),e.getAnalysis());}public Response save(String u,Create d){AnalysisHistory e=new AnalysisHistory();e.setUserId(u);e.setReportId(d.reportId());e.setAnalysis(Map.copyOf(d.analysis()));e.setAnalyzedAt(Instant.now());return dto(r.save(e));}public List<Response> list(String u){return r.findByUserIdOrderByAnalyzedAtDesc(u).stream().map(this::dto).toList();}public Response get(String u,String id){return dto(r.findById(id).filter(e->e.getUserId().equals(u)).orElseThrow(()->new ResourceNotFoundException("Analysis not found")));}}
